import{z as l,x as s,o as A,c as C,q as r,j as n,D as e,d as B,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"债券组合收束","description":"","frontmatter":{"title":"债券组合收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-map.md","filePath":"quant/bm2-map.md","lastUpdated":1791413859000}'),d={name:"quant/bm2-map.md"};function m(p,E,F,D,u,h){const t=s("Mermaid");return A(),C("div",null,[E[2]||(E[2]=r('<h1 id="债券组合收束" tabindex="-1">债券组合收束 <a class="header-anchor" href="#债券组合收束" aria-label="Permalink to &quot;债券组合收束&quot;">​</a></h1><div class="epigraph"><p>债券组合管理的全部内容，是把一张负债表与一条曲线之间的距离，用可交易的工具与可执行的条款补上——工具决定快慢，条款决定生死。</p><footer>—— 据 Fabozzi 相关章节整理；因子分解口径出自 Litterman and Scheinkman, Journal of Fixed Income, 1991</footer></div><p><a href="/quant/bm2-case">上一课</a>把工具按次序装进一台完整组合，从负债档案走到压力报告。本课程到此收束：本课把八课收成一张地图——策略空间、工具空间、风险空间，以及反复出现的三个取舍，判据各归各课，不重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束的问题是「什么在泛化」。八课之后留下的不应是几张参数表，而是一套决策程序：风险单位由负债定义；暴露沿因子分解记账；工具按含抵押的总成本选；所有模型管不住的残差写成限额与触发线。检验收束是否成立的方法是反向走一遍：给定任一台债券组合，能否在半小时内说出它的负债基准是什么、每个桶用什么工具覆盖、利差与相关记在哪本账、抵押缺口在哪条触发线后面——答不上来的那一项，就是它的结构漏洞。</p><p><span class="marginnote">术语翻译：「泛化」在这里就是从例题到考题。八课是例题，考题是换一台陌生组合，还能不能在半小时内说清它的负债基准、每个桶的覆盖工具、利差与相关记在哪本账、抵押缺口在哪条触发线后面——验的不是记住了多少参数，而是有没有一套能重新长出参数的程序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个空间并成一张图。策略空间从浅到深：单笔负债的 <a href="/quant/bm2-duration-immunization">久期免疫</a>、以负债函数为基准的 <a href="/quant/bm2-ldi">LDI</a>、以市场指数为基准的 <a href="/quant/bm2-bond-indexing">指数化</a>、以及主动管理信用损失分布的 <a href="/quant/bm2-credit-diversification">分散</a>——四者共用一套风险语言，只是基准从单点换成函数再换成分布。工具空间按资金占用与条款密度排列：现券（付全款、留凸性与 carry）、<a href="/quant/bm2-treasury-futures">期货</a>（标准化、CTD 刻度、逐日盯市）、<a href="/quant/bm2-swaps-in-portfolio">互换</a>（期限任选、CSA 条款）、指数与 CDS（系统层承载）。风险空间沿用 <a href="/quant/curve-pca">曲线 PCA</a> 的三因子加利差与相关：任何组合都是在这几个方向上的头寸表，<a href="/quant/key-tenor-dv01">关键期限 DV01</a> 向量是它的可执行写法。</p>',8)),(A(),n(o,null,{default:e(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LB%5B%22%E8%B4%9F%E5%80%BA%E5%AE%9A%E4%B9%89%E9%A3%8E%E9%99%A9%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20F%5B%22%E5%9B%A0%E5%AD%90%E8%AE%B0%E8%B4%A6%EF%BC%9A%E6%B0%B4%E5%B9%B3%E3%80%81%E9%99%A1%E5%B3%AD%E3%80%81%E6%9B%B2%E7%8E%87%E3%80%81%E5%88%A9%E5%B7%AE%E3%80%81%E7%9B%B8%E5%85%B3%22%5D%0A%20%20F%20--%3E%20T1%5B%22%E7%8E%B0%E5%88%B8%EF%BC%9A%E4%BB%98%E5%85%A8%E6%AC%BE%EF%BC%8C%E7%95%99%E5%87%B8%E6%80%A7%E4%B8%8E%20carry%22%5D%0A%20%20F%20--%3E%20T2%5B%22%E6%9C%9F%E8%B4%A7%EF%BC%9A%E6%A0%87%E5%87%86%E5%8C%96%EF%BC%8CCTD%20%E5%88%BB%E5%BA%A6%22%5D%0A%20%20F%20--%3E%20T3%5B%22%E4%BA%92%E6%8D%A2%EF%BC%9A%E6%9C%9F%E9%99%90%E4%BB%BB%E9%80%89%EF%BC%8CCSA%20%E6%9D%A1%E6%AC%BE%22%5D%0A%20%20F%20--%3E%20T4%5B%22%E6%8C%87%E6%95%B0%E4%B8%8E%20CDS%EF%BC%9A%E7%B3%BB%E7%BB%9F%E5%B1%82%22%5D%0A%20%20T1%20--%3E%20TR%5B%22%E4%B8%89%E4%B8%AA%E5%8F%96%E8%88%8D%EF%BC%9A%E5%9F%BA%E5%B7%AE%E4%B8%8E%E6%88%90%E6%9C%AC%E3%80%81%E7%B2%92%E5%BA%A6%E4%B8%8E%E4%BB%B7%E5%B7%AE%E3%80%81%E4%B8%80%E9%98%B6%E4%B8%8E%E4%BA%8C%E9%98%B6%22%5D%0A%20%20T2%20--%3E%20TR%0A%20%20T3%20--%3E%20TR%0A%20%20T4%20--%3E%20TR%0A%20%20TR%20--%3E%20LM%5B%22%E6%AE%8B%E5%B7%AE%E5%86%99%E6%88%90%E9%99%90%E9%A2%9D%E4%B8%8E%E8%A7%A6%E5%8F%91%E7%BA%BF%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("三个取舍贯穿全部八课，值得点名。其一，基差与成本：期货与互换比现券便宜，便宜的部分以基差形式回收——CTD 切换、互换—国债利差、指数成分差，都是在工具省下的钱里埋着的头寸；用工具前先问基差记在哪本账。其二，粒度与价差：分散的算术要求名字多、权重匀，流动性的账单随冷门券上升，粒度最终是花价差买来的。其三，一阶与二阶：免疫只保一阶，凸性差与曲线扭转是真实的损益，把二阶当「高阶小量」的组合作在大幅移动的年份把一阶省下的全部还回去。三条取舍之下是同一条暗线：抵押与流动性是传导链的上游，2022 年的 gilt 螺旋把这条线写进了所有方案的治理条款——"),a("a",{href:"/quant/rc-case-map"},"利率信用案例"),B("收束时的判据，在本课程以组合的口径再次兑现。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"收束自查的三问：基准是负债函数还是指数、每个久期桶的覆盖工具与其基差账本、压力场景里有没有追保路径——三问答不全，组合的结构性风险就没有写完。")],-1)),(A(),n(o,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E9%9C%80%E8%A6%81%E8%A1%A5%E4%B9%85%E6%9C%9F%E6%9A%B4%E9%9C%B2%EF%BC%9A%E7%94%A8%E4%BB%80%E4%B9%88%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20Q1%7B%22%E5%8F%96%E8%88%8D%E4%B8%80%EF%BC%9A%E5%9F%BA%E5%B7%AE%E4%B8%8E%E6%88%90%E6%9C%AC%22%7D%0A%20%20Q1%20--%3E%20F%5B%22%E6%9C%9F%E8%B4%A7%EF%BC%9A%E4%BE%BF%E5%AE%9C%EF%BC%8CCTD%20%E5%88%87%E6%8D%A2%E8%AE%B0%E8%BF%9B%E5%9F%BA%E5%B7%AE%E8%B4%A6%22%5D%0A%20%20Q1%20--%3E%20C%5B%22%E7%8E%B0%E5%88%B8%EF%BC%9A%E4%BB%98%E5%85%A8%E6%AC%BE%EF%BC%8C%E6%8D%A2%E5%B9%B2%E5%87%80%E6%9A%B4%E9%9C%B2%E4%B8%8E%E5%87%B8%E6%80%A7%22%5D%0A%20%20F%20--%3E%20Q2%7B%22%E5%8F%96%E8%88%8D%E4%BA%8C%EF%BC%9A%E7%B2%92%E5%BA%A6%E4%B8%8E%E4%BB%B7%E5%B7%AE%22%7D%0A%20%20C%20--%3E%20Q2%0A%20%20Q2%20--%3E%20G1%5B%22%E8%A6%81%E6%95%A3%EF%BC%9A%E5%A4%9A%E5%88%B8%E5%88%86%E6%95%A3%EF%BC%8C%E6%8C%89%E4%BB%B7%E5%B7%AE%E4%BB%98%E8%B4%A6%22%5D%0A%20%20Q2%20--%3E%20G2%5B%22%E8%A6%81%E5%87%86%EF%BC%9A%E5%8D%95%E7%82%B9%E5%B7%A5%E5%85%B7%EF%BC%8C%E6%8E%A5%E5%8F%97%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A%20%20G1%20--%3E%20Q3%7B%22%E5%8F%96%E8%88%8D%E4%B8%89%EF%BC%9A%E4%B8%80%E9%98%B6%E4%B8%8E%E4%BA%8C%E9%98%B6%22%7D%0A%20%20G2%20--%3E%20Q3%0A%20%20Q3%20--%3E%20R%5B%22%E4%BA%8C%E9%98%B6%E6%AE%8B%E5%B7%AE%E5%86%99%E6%88%90%E9%99%90%E9%A2%9D%E4%B8%8E%E8%A7%A6%E5%8F%91%E7%BA%BF%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">数字实例：「二阶是小量」在大幅移动时不成立。取现值 1000 万、久期 8.8、凸性约 80 的组合，收益率一次性上行 5%：一阶损失约 \\(1000\\text{万} \\times 8.8 \\times 0.05 = 440\\) 万元，二阶项 \\(0.5 \\times 80 \\times 1000\\text{万} \\times 0.05^2 = 100\\) 万元——超过一阶的两成，免疫的对冲若无凸性安排，这就是漏进来的损益。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程的边界与它的口径绑定：曲线本身如何构建是 <a href="/quant/curve-bootstrap">自举曲线</a> 的领地，参数族的光滑问题见 <a href="/quant/nelson-siegel">Nelson–Siegel</a>；利差与 XVA 的资金链在利率信用深化课程里；组合层面的压力与归因分别有专门的深化课程。本课程没有写的还有：跨币种负债与汇率对冲、通胀工具的细节、证券化产品的负凸性、以及 alpha 的来源——这些都是相邻课程的题目，不是收束能代答的。最后，地图上每个工具的条款都会随制度漂移：保证金规则、基准利率、指数编制方法都在变，收束留下的是决策程序，不是参数表。</p><p><span class="marginnote">为什么重要：这张地图如果当参数表背，半年就过期——保证金规则、指数编制方法、基准利率都在漂移；当决策程序用，则每次遇到新工具都能重新问出同一组问题：基差记在哪本账、价差付了多少、二阶残差写限额了吗。程序不过期，参数才会。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略空间共一套风险语言：免疫、LDI、指数化、信用分散，差别只在基准是点、函数还是分布。</li><li>工具空间按资金与条款排列：现券、期货、互换、指数，选择标准是含抵押的总成本。</li><li>三个取舍贯穿全课：基差与成本、粒度与价差、一阶与二阶。</li><li>风险空间是三因子加利差与相关，可执行写法是关键期限 DV01 向量。</li><li>出处：据 Fabozzi 相关章节整理；因子分解出自 Litterman and Scheinkman, Journal of Fixed Income, 1991，各课判据见本课程相应课。</li></ul>',6))])}const T=l(d,[["render",m]]);export{c as __pageData,T as default};
